#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define TILE_DIM_PADDED 33 // TILE_DIM + 1 to avoid bank conflicts

__global__ void matrix_mul_kernel_tiled_padded(const float* A, const float* B, float* C, int M, int N, int K) {
    __shared__ float As[TILE_DIM][TILE_DIM_PADDED];
    __shared__ float Bs[TILE_DIM][TILE_DIM_PADDED];

    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    int row = blockRow * TILE_DIM + threadIdx.y;
    int col = blockCol * TILE_DIM + threadIdx.x;

    float Cvalue = 0.0f;

    for (int t = 0; t < (K + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tiles into shared memory
        // Coalesced load for A
        if (row < M && (t * TILE_DIM + threadIdx.x) < K) {
            As[threadIdx.y][threadIdx.x] = A[row * K + (t * TILE_DIM + threadIdx.x)];
        } else {
